<?php $page_title='Campaigns'; require_once 'includes/header.php'; require_login(); $rows=$pdo->query("SELECT * FROM campaigns WHERE status IN ('active','completed') ORDER BY status='active' DESC, created_at DESC")->fetchAll(); ?>
<section class="page-hero"><span class="kicker">COMMUNITY CAMPAIGNS</span><h1>Turn a donation into a movement.</h1><p>Join food rescue drives, support meal targets and follow real community progress.</p></section><div class="campaign-public-grid"><?php foreach($rows as $c):$pct=$c['target_meals']?min(100,round($c['raised_meals']/$c['target_meals']*100)):0;?><article class="campaign-public-card"><div class="campaign-icon">📣</div><span class="badge <?=badge_class($c['status'])?>"><?=e($c['status'])?></span><h2><?=e($c['title'])?></h2><p><?=e($c['description'])?></p><div class="progress"><span style="width:<?=$pct?>%"></span></div><div class="campaign-numbers"><b><?=intval($c['raised_meals'])?></b><span>/ <?=intval($c['target_meals'])?> meals</span><span>📍 <?=e($c['location']?:'Community')?></span></div></article><?php endforeach;if(!$rows):?><div class="empty-state full">No campaigns are active right now.</div><?php endif;?></div>
